contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Ensure the caller's stored balance is strictly below MinSum during Collect.
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        bool collectReverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        uint afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        // The precondition is encoded in the assertion: if the caller is below MinSum,
        // Collect must not change balances or the contract's Ether balance.
        assert(beforeBalance >= c.MinSum() || (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance));
    }

    receive() external payable {}
}

