pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmount, uint256 collectAmount, uint256 minSum) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 beforeBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 afterBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue(beforeBalance >= c.MinSum() || (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance));
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        _run(depositAmount, collectAmount, minSum);
    }

    receive() external payable {}
}
